CREATE COLUMN TABLE "TEST_AP"."ORCN" ("ChainCode" INTEGER CS_INT NOT NULL , "ChainName" NVARCHAR(20) NOT NULL , "SuppNum" NVARCHAR(20), "SuppName" NVARCHAR(20), "Locked" NVARCHAR(1) DEFAULT 'N', "SavePath" NCLOB MEMORY THRESHOLD 1000, "UsePartSup" NVARCHAR(1) DEFAULT 'N', "BaseCode" INTEGER CS_INT DEFAULT -1, "DataSource" NVARCHAR(1) DEFAULT 'N', "ExportNum" INTEGER CS_INT DEFAULT 0, "UserSign" SMALLINT CS_INT, PRIMARY KEY ("ChainCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ORCN_NAME" ON "TEST_AP"."ORCN" ( "ChainName" ASC )